CustomField.formula:
IF(
OR(

/* Logged in user owns the visit */
cgcloud__Responsible__c = $User.Id,

/* NSM parent territory coverage */
AND(
    NOT(ISBLANK($User.TPB_Territory__c)),
    cgcloud__Responsible__r.TPB_Parent_Territory__c = $User.TPB_Territory__c
),

/* Directors (NSD) whose region prefix matches */
AND(
    $User.Title = "NSD",
    LEFT($User.Territory_Id__c,2) = LEFT(cgcloud__Responsible__r.Territory_Id__c,2)
),

/* Admin override */
$Profile.Name = "System Administrator",

/* Executive role */
$UserRole.Name = "Executive"

),
1,
0
)
